import React, { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useApp } from "../context/AppContext";
import PomodoroTimer from "../components/PomodoroTimer";
import TaskList from "../components/TaskList";
import StarsDisplay from "../components/StarsDisplay";

// ─── Badge catalog (mirrors DB seed) ────────────────────────────────────────
const BADGE_CATALOG = [
  {
    emoji: "⭐",
    name: "Primera Estrella",
    desc: "Completa tu primera sesión",
    type: "sessions",
    value: 1,
  },
  {
    emoji: "🔥",
    name: "En Racha",
    desc: "3 días seguidos de estudio",
    type: "streak",
    value: 3,
  },
  {
    emoji: "🏆",
    name: "Campeón del Foco",
    desc: "Completa 10 sesiones de enfoque",
    type: "sessions",
    value: 10,
  },
  {
    emoji: "🚀",
    name: "Despegue",
    desc: "Alcanza el Nivel 5",
    type: "level",
    value: 5,
  },
  {
    emoji: "💎",
    name: "Diamante",
    desc: "Acumula 500 estrellas",
    type: "stars",
    value: 500,
  },
  {
    emoji: "🎯",
    name: "Puntería Perfecta",
    desc: "Completa 5 tareas",
    type: "tasks",
    value: 5,
  },
  {
    emoji: "⚡",
    name: "Súper Velocidad",
    desc: "Completa una tarea en tiempo récord",
    type: "tasks",
    value: 1,
  },
  {
    emoji: "🌟",
    name: "Superestrella",
    desc: "Completa 25 sesiones",
    type: "sessions",
    value: 25,
  },
];

function getBadgeProgress(profile, badge) {
  const map = {
    sessions: profile.sessionsCompleted || 0,
    streak: profile.streak || 0,
    level: profile.level || 1,
    stars: profile.stars || 0,
    tasks: profile.tasksCompleted || 0,
  };
  return { current: map[badge.type] ?? 0, max: badge.value };
}

// ─── Learn tips ──────────────────────────────────────────────────────────────
const LEARNING_TIPS = [
  {
    emoji: "🧠",
    title: "El secreto del Pomodoro",
    body: "Tu cerebro aprende mejor en bloques cortos. 25 minutos de enfoque total es el tiempo perfecto para recordar todo.",
  },
  {
    emoji: "💧",
    title: "Hidrátate mientras estudias",
    body: "Beber agua ayuda a tu cerebro a funcionar mejor. ¡Toma un vaso durante cada descanso!",
  },
  {
    emoji: "😴",
    title: "Los descansos importan",
    body: "Durante el descanso tu cerebro organiza la información que aprendiste. ¡No los saltes!",
  },
  {
    emoji: "✏️",
    title: "Escribe a mano",
    body: "Tomar notas a mano ayuda a recordar mejor que escribir en computadora. ¡Pruébalo!",
  },
  {
    emoji: "🎵",
    title: "Música para concentrarte",
    body: "La música instrumental sin letra puede ayudarte a mantener el foco más tiempo.",
  },
  {
    emoji: "🌳",
    title: "Espacio limpio, mente clara",
    body: "Un lugar ordenado y sin distracciones hace que tu cerebro trabaje mucho más rápido.",
  },
  {
    emoji: "🔄",
    title: "Repasa lo que aprendiste",
    body: "Después de cada sesión, tómate 2 minutos para repasar los puntos más importantes del tema.",
  },
  {
    emoji: "🎉",
    title: "Celebra tus logros",
    body: "¡Por eso ganás estrellas! Celebrar pequeños avances te da fuerza para seguir aprendiendo.",
  },
];

const STUDY_CHALLENGES = [
  {
    emoji: "🎯",
    title: "Reto del día",
    desc: "Completa 2 sesiones de enfoque hoy",
    stars: 40,
  },
  {
    emoji: "📖",
    title: "Lectura profunda",
    desc: "Lee 15 minutos sin distracciones",
    stars: 30,
  },
  {
    emoji: "🧩",
    title: "Desafío mental",
    desc: "Resuelve 5 problemas de matemáticas",
    stars: 50,
  },
  {
    emoji: "✍️",
    title: "Escritura creativa",
    desc: "Escribe 3 cosas nuevas que aprendiste hoy",
    stars: 20,
  },
];

// ─── Main component ──────────────────────────────────────────────────────────
export default function Dashboard() {
  const { state, dispatch } = useApp();
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState("timer");

  useEffect(() => {
    if (!state.activeProfile) navigate("/");
  }, [state.activeProfile, navigate]);

  useEffect(() => {
    if (state.timerState === "completed" && state.lastReward) {
      const timer = setTimeout(() => navigate("/reward"), 1200);
      return () => clearTimeout(timer);
    }
  }, [state.timerState, state.lastReward, navigate]);

  if (!state.activeProfile) return null;
  const profile = state.activeProfile;

  const NAV_TABS = [
    { key: "timer", icon: "timer", label: "Timer" },
    { key: "logros", icon: "workspace_premium", label: "Logros" },
    { key: "aprender", icon: "auto_stories", label: "Aprender" },
    { key: "perfil", icon: "person", label: "Perfil" },
  ];

  return (
    <div
      className="min-h-screen bg-bg-light flex flex-col"
      style={{ minHeight: "100dvh" }}
    >
      {/* Header */}
      <header className="flex items-center justify-between p-5 pt-6">
        <button
          onClick={() => navigate("/")}
          className="w-12 h-12 flex items-center justify-center bg-white rounded-full shadow-sm hover:bg-slate-50 active:scale-90 transition-all"
          aria-label="Menú"
        >
          <span className="material-symbols-outlined text-primary">menu</span>
        </button>
        <h2 className="font-display text-2xl text-primary">FocusKids</h2>
        <button
          onClick={() => setActiveTab("perfil")}
          className="w-12 h-12 flex items-center justify-center bg-white rounded-full shadow-sm overflow-hidden hover:ring-2 hover:ring-primary transition-all"
          aria-label="Perfil"
        >
          <span
            className={`text-2xl ${profile.avatar?.bg || "bg-orange-100"} w-full h-full flex items-center justify-center`}
          >
            {profile.avatar?.emoji || "🦄"}
          </span>
        </button>
      </header>

      <main className="flex-1 px-5 pb-24 overflow-y-auto">
        {/* Stars bar */}
        <div className="flex items-center justify-between mb-4">
          <div>
            <p className="text-slate-500 text-sm font-semibold">
              Hola, <span className="text-primary">{profile.name}!</span>
            </p>
            <p className="text-xs text-slate-400">
              Nivel {profile.level} · {profile.streak} días seguidos 🔥
            </p>
          </div>
          <StarsDisplay />
        </div>

        {/* Tab panels */}
        {activeTab === "timer" && <TimerPanel />}
        {activeTab === "logros" && <LogrosPanel profile={profile} />}
        {activeTab === "aprender" && (
          <AprenderPanel profile={profile} dispatch={dispatch} />
        )}
        {activeTab === "perfil" && (
          <PerfilPanel
            profile={profile}
            navigate={navigate}
            dispatch={dispatch}
          />
        )}
      </main>

      {/* Bottom Nav */}
      <nav className="fixed bottom-0 left-1/2 -translate-x-1/2 w-full max-w-md bg-white/90 backdrop-blur-md border-t border-slate-100 px-5 py-3 z-40">
        <div className="flex justify-between items-center">
          {NAV_TABS.map(({ key, icon, label }) => (
            <button
              key={key}
              type="button"
              onClick={() => setActiveTab(key)}
              className={`flex flex-col items-center gap-1 bg-transparent border-none p-0 transition-colors ${activeTab === key ? "text-primary" : "text-slate-400"}`}
            >
              <span
                className={`material-symbols-outlined ${activeTab === key ? "fill-icon" : ""}`}
              >
                {icon}
              </span>
              <span className="text-xs font-bold">{label}</span>
            </button>
          ))}
        </div>
      </nav>
    </div>
  );
}

// ─── Timer tab ───────────────────────────────────────────────────────────────
function TimerPanel() {
  return (
    <>
      <PomodoroTimer />
      <TaskList />
    </>
  );
}

// ─── Logros tab ──────────────────────────────────────────────────────────────
function LogrosPanel({ profile }) {
  const earned = BADGE_CATALOG.filter((b) => {
    const { current, max } = getBadgeProgress(profile, b);
    return current >= max;
  });
  const pending = BADGE_CATALOG.filter((b) => {
    const { current, max } = getBadgeProgress(profile, b);
    return current < max;
  });

  return (
    <div className="space-y-6">
      {/* Summary */}
      <div className="grid grid-cols-3 gap-3">
        {[
          {
            label: "Insignias",
            value: earned.length,
            color: "bg-accent-yellow/20 text-amber-600",
            icon: "🏅",
          },
          {
            label: "Sesiones",
            value: profile.sessionsCompleted || 0,
            color: "bg-primary/10 text-primary",
            icon: "⏱️",
          },
          {
            label: "Racha",
            value: `${profile.streak || 0}d`,
            color: "bg-orange-100 text-orange-500",
            icon: "🔥",
          },
        ].map(({ label, value, color, icon }) => (
          <div key={label} className={`${color} rounded-2xl p-3 text-center`}>
            <div className="text-2xl mb-1">{icon}</div>
            <div className="font-display text-xl">{value}</div>
            <div className="text-xs font-bold opacity-70">{label}</div>
          </div>
        ))}
      </div>

      {/* Earned badges */}
      {earned.length > 0 && (
        <section>
          <h3 className="font-display text-xl text-slate-800 mb-3">
            ✨ Logros Conseguidos
          </h3>
          <div className="grid grid-cols-2 gap-3">
            {earned.map((badge) => (
              <div
                key={badge.name}
                className="bg-white rounded-2xl p-4 border-2 border-accent-yellow/40 shadow-sm flex items-center gap-3"
              >
                <div className="w-14 h-14 rounded-2xl bg-accent-yellow/20 flex items-center justify-center text-3xl flex-shrink-0">
                  {badge.emoji}
                </div>
                <div className="min-w-0">
                  <p className="font-bold text-slate-800 text-sm leading-tight">
                    {badge.name}
                  </p>
                  <p className="text-xs text-slate-400 mt-0.5 leading-tight">
                    {badge.desc}
                  </p>
                  <span className="text-xs font-bold text-accent-green">
                    ✅ Obtenido
                  </span>
                </div>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* Pending badges */}
      <section>
        <h3 className="font-display text-xl text-slate-800 mb-3">
          🔒 Por Desbloquear
        </h3>
        <div className="space-y-3">
          {pending.map((badge) => {
            const { current, max } = getBadgeProgress(profile, badge);
            const pct = Math.min(Math.round((current / max) * 100), 100);
            return (
              <div
                key={badge.name}
                className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm flex items-center gap-4"
              >
                <div className="w-14 h-14 rounded-2xl bg-slate-100 flex items-center justify-center text-3xl flex-shrink-0 grayscale opacity-50">
                  {badge.emoji}
                </div>
                <div className="flex-1 min-w-0">
                  <p className="font-bold text-slate-700 text-sm">
                    {badge.name}
                  </p>
                  <p className="text-xs text-slate-400 mb-2">{badge.desc}</p>
                  <div className="h-2 bg-slate-100 rounded-full overflow-hidden">
                    <div
                      className="h-full bg-gradient-to-r from-primary to-accent-yellow rounded-full transition-all duration-700"
                      style={{ width: `${pct}%` }}
                    />
                  </div>
                  <p className="text-xs text-slate-400 mt-1">
                    {current} / {max}
                  </p>
                </div>
              </div>
            );
          })}
        </div>
      </section>

      {earned.length === 0 && pending.length === 0 && (
        <div className="text-center py-16">
          <div className="text-6xl mb-3">🏅</div>
          <p className="text-slate-500 font-semibold">
            ¡Completa sesiones para ganar insignias!
          </p>
        </div>
      )}
    </div>
  );
}

// ─── Aprender tab ─────────────────────────────────────────────────────────────
function AprenderPanel({ profile }) {
  const [tipIdx, setTipIdx] = useState(0);
  const tip = LEARNING_TIPS[tipIdx];

  return (
    <div className="space-y-6">
      {/* Featured tip carousel */}
      <div className="bg-gradient-to-br from-primary to-orange-400 rounded-3xl p-5 text-white shadow-xl shadow-primary/30">
        <p className="text-xs font-bold uppercase tracking-widest opacity-80 mb-1">
          Consejo de Estudio
        </p>
        <div className="text-5xl mb-3">{tip.emoji}</div>
        <h3 className="font-display text-2xl mb-2 leading-tight">
          {tip.title}
        </h3>
        <p className="text-sm opacity-90 leading-relaxed">{tip.body}</p>
        <div className="flex items-center justify-between mt-4">
          <div className="flex gap-1.5">
            {LEARNING_TIPS.map((_, i) => (
              <button
                key={i}
                type="button"
                onClick={() => setTipIdx(i)}
                className={`w-2 h-2 rounded-full transition-all border-none p-0 ${i === tipIdx ? "bg-white w-5" : "bg-white/40"}`}
              />
            ))}
          </div>
          <div className="flex gap-2">
            <button
              type="button"
              onClick={() =>
                setTipIdx(
                  (i) => (i - 1 + LEARNING_TIPS.length) % LEARNING_TIPS.length,
                )
              }
              className="w-9 h-9 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center border-none transition-colors"
            >
              <span className="material-symbols-outlined text-lg">
                chevron_left
              </span>
            </button>
            <button
              type="button"
              onClick={() => setTipIdx((i) => (i + 1) % LEARNING_TIPS.length)}
              className="w-9 h-9 rounded-full bg-white/20 hover:bg-white/30 flex items-center justify-center border-none transition-colors"
            >
              <span className="material-symbols-outlined text-lg">
                chevron_right
              </span>
            </button>
          </div>
        </div>
      </div>

      {/* Daily challenges */}
      <section>
        <h3 className="font-display text-xl text-slate-800 mb-3">
          🎮 Desafíos de Hoy
        </h3>
        <div className="space-y-3">
          {STUDY_CHALLENGES.map((ch, i) => (
            <div
              key={ch.title}
              className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm flex items-center gap-4"
            >
              <div
                className={`w-14 h-14 rounded-2xl flex items-center justify-center text-3xl flex-shrink-0 ${
                  i === 0
                    ? "bg-primary/10"
                    : i === 1
                      ? "bg-accent-green/10"
                      : i === 2
                        ? "bg-indigo-100"
                        : "bg-accent-yellow/20"
                }`}
              >
                {ch.emoji}
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-bold text-slate-800 text-sm">{ch.title}</p>
                <p className="text-xs text-slate-400 mt-0.5">{ch.desc}</p>
              </div>
              <div className="flex flex-col items-center flex-shrink-0">
                <span className="text-lg">⭐</span>
                <span className="text-xs font-bold text-amber-500">
                  +{ch.stars}
                </span>
              </div>
            </div>
          ))}
        </div>
      </section>

      {/* All tips grid */}
      <section>
        <h3 className="font-display text-xl text-slate-800 mb-3">
          📚 Todos los Consejos
        </h3>
        <div className="grid grid-cols-2 gap-3">
          {LEARNING_TIPS.map((t, i) => (
            <button
              key={t.title}
              type="button"
              onClick={() => setTipIdx(i)}
              className={`text-left p-4 rounded-2xl border-2 transition-all active:scale-95 ${
                i === tipIdx
                  ? "border-primary bg-primary/5"
                  : "border-slate-100 bg-white"
              }`}
            >
              <div className="text-2xl mb-2">{t.emoji}</div>
              <p className="font-bold text-slate-800 text-xs leading-tight">
                {t.title}
              </p>
            </button>
          ))}
        </div>
      </section>
    </div>
  );
}

// ─── Perfil tab ──────────────────────────────────────────────────────────────
function PerfilPanel({ profile, navigate, dispatch }) {
  const [editing, setEditing] = useState(false);
  const [nameInput, setNameInput] = useState(profile.name);

  const starsToNextLevel = 100 - (profile.stars % 100);
  const levelPct = Math.min(profile.stars % 100, 100);

  const handleSaveName = () => {
    if (nameInput.trim() && nameInput.trim() !== profile.name) {
      dispatch({
        type: "UPDATE_PROFILE_NAME",
        payload: { id: profile.id, name: nameInput.trim() },
      });
    }
    setEditing(false);
  };

  const earnedBadges = BADGE_CATALOG.filter((b) => {
    const { current, max } = getBadgeProgress(profile, b);
    return current >= max;
  });

  return (
    <div className="space-y-5">
      {/* Avatar card */}
      <div className="bg-white rounded-3xl p-6 border border-slate-100 shadow-sm flex flex-col items-center">
        <div
          className={`w-24 h-24 rounded-full ${profile.avatar?.bg || "bg-orange-100"} flex items-center justify-center text-5xl shadow-lg mb-3`}
        >
          {profile.avatar?.emoji || "🦄"}
        </div>

        {editing ? (
          <div className="flex items-center gap-2 w-full max-w-xs">
            <input
              autoFocus
              type="text"
              value={nameInput}
              onChange={(e) => setNameInput(e.target.value)}
              onKeyDown={(e) => e.key === "Enter" && handleSaveName()}
              maxLength={15}
              className="flex-1 border-2 border-primary rounded-xl px-3 py-2 font-bold text-center text-lg focus:outline-none"
            />
            <button
              type="button"
              onClick={handleSaveName}
              className="w-10 h-10 rounded-xl bg-primary text-white flex items-center justify-center border-none"
            >
              <span className="material-symbols-outlined text-lg">check</span>
            </button>
          </div>
        ) : (
          <div className="flex items-center gap-2">
            <h2 className="font-display text-3xl text-slate-800">
              {profile.name}
            </h2>
            <button
              type="button"
              onClick={() => {
                setEditing(true);
                setNameInput(profile.name);
              }}
              className="w-8 h-8 rounded-full bg-slate-100 hover:bg-slate-200 flex items-center justify-center border-none transition-colors"
            >
              <span className="material-symbols-outlined text-base text-slate-500">
                edit
              </span>
            </button>
          </div>
        )}

        {/* Level badge */}
        <div className="flex items-center gap-2 mt-2">
          <span className="bg-primary text-white text-sm font-bold px-3 py-1 rounded-full">
            Nivel {profile.level}
          </span>
          <span className="text-sm text-slate-400 font-semibold">
            ⭐ {profile.stars} estrellas
          </span>
        </div>

        {/* XP bar */}
        <div className="w-full mt-4">
          <div className="flex justify-between text-xs text-slate-400 font-semibold mb-1">
            <span>Nivel {profile.level}</span>
            <span>
              {starsToNextLevel} ⭐ para Nivel {profile.level + 1}
            </span>
          </div>
          <div className="h-3 bg-slate-100 rounded-full overflow-hidden">
            <div
              className="h-full bg-gradient-to-r from-primary to-accent-yellow rounded-full transition-all duration-700"
              style={{ width: `${levelPct}%` }}
            />
          </div>
        </div>
      </div>

      {/* Stats grid */}
      <div className="grid grid-cols-2 gap-3">
        {[
          {
            icon: "⏱️",
            label: "Sesiones",
            value: profile.sessionsCompleted || 0,
            bg: "bg-primary/10",
            text: "text-primary",
          },
          {
            icon: "✅",
            label: "Tareas",
            value: profile.tasksCompleted || 0,
            bg: "bg-accent-green/10",
            text: "text-accent-green",
          },
          {
            icon: "🔥",
            label: "Racha actual",
            value: `${profile.streak || 0}d`,
            bg: "bg-orange-100",
            text: "text-orange-500",
          },
          {
            icon: "🏅",
            label: "Insignias",
            value: earnedBadges.length,
            bg: "bg-accent-yellow/20",
            text: "text-amber-600",
          },
        ].map(({ icon, label, value, bg, text }) => (
          <div
            key={label}
            className={`${bg} ${text} rounded-2xl p-4 flex items-center gap-3`}
          >
            <span className="text-3xl">{icon}</span>
            <div>
              <div className="font-display text-2xl leading-none">{value}</div>
              <div className="text-xs font-bold opacity-70 mt-0.5">{label}</div>
            </div>
          </div>
        ))}
      </div>

      {/* Badges showcase */}
      {earnedBadges.length > 0 && (
        <div className="bg-white rounded-2xl p-4 border border-slate-100 shadow-sm">
          <h3 className="font-display text-lg text-slate-800 mb-3">
            🏆 Mis Insignias
          </h3>
          <div className="flex flex-wrap gap-3">
            {earnedBadges.map((b) => (
              <div
                key={b.name}
                className="flex flex-col items-center gap-1 w-14"
              >
                <div className="w-12 h-12 rounded-2xl bg-accent-yellow/20 flex items-center justify-center text-2xl">
                  {b.emoji}
                </div>
                <span className="text-xs text-center text-slate-500 font-semibold leading-tight">
                  {b.name}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Motivational message */}
      <div className="bg-gradient-to-br from-accent-green/20 to-accent-green/5 rounded-2xl p-4 flex items-center gap-3 border border-accent-green/20">
        <span className="text-3xl">💪</span>
        <div>
          <p className="font-bold text-accent-green text-sm">
            {(profile.sessionsCompleted || 0) === 0
              ? "¡Completa tu primera sesión hoy!"
              : (profile.streak || 0) >= 3
                ? `¡Increíble racha de ${profile.streak} días, ${profile.name}!`
                : `¡Sigue así, ${profile.name}! Cada sesión te hace más inteligente.`}
          </p>
          <p className="text-xs text-slate-500 mt-0.5">
            FocusKids cree en ti 🚀
          </p>
        </div>
      </div>

      {/* Switch profile */}
      <button
        type="button"
        onClick={() => navigate("/")}
        className="w-full bg-slate-100 text-slate-600 py-4 rounded-2xl font-bold text-base hover:bg-slate-200 active:scale-95 transition-all flex items-center justify-center gap-2"
      >
        <span className="material-symbols-outlined">swap_horiz</span>
        Cambiar Perfil
      </button>
    </div>
  );
}
